iso:principle_am_value a iso:Concept ;
  rdfs:label "value (asset management principle)" ;
  iso:provenanceStandard "ISO 55000:2024" ;
  iso:provenanceClause "4.2.2" ;
  iso:definition "Asset management focuses on the value assets provide to the organization over time. This principle encourages clear contributions to organizational objectives, life cycle management and transparent decision-making processes." ;
  iso:pdmRelevance "medium" .

iso:principle_am_alignment a iso:Concept ;
  rdfs:label "alignment (asset management principle)" ;
  iso:provenanceStandard "ISO 55000:2024" ;
  iso:provenanceClause "4.2.3" ;
  iso:definition "asset management aligns financial, technical and operational decisions with the organizational objectives, promoting vertical and horizontal coordination" ;
  iso:pdmRelevance "high" .

iso:principle_am_leadership a iso:Concept ;
  rdfs:label "leadership (asset management principle)" ;
  iso:provenanceStandard "ISO 55000:2024" ;
  iso:provenanceClause "4.2.4" ;
  iso:definition "Leadership and sustained commitment at all levels are crucial for successful asset management. Effective leadership establishes a clear direction, roles, responsibilities and authorities, with transparent consultation and the development of a collaborative culture that is aligned to organizational success." ;
  iso:pdmRelevance "low" .

iso:term_am_maturity a iso:Concept ;
  rdfs:label "asset management maturity" ;
  iso:provenanceStandard "ISO 55000:2024" ;
  iso:provenanceClause "4.5" ;
  iso:definition "Asset management maturity is key to enhancing an organization's performance. The organization's progress can be measured by its maturity: showing how well it is performing and where targeted improvements can be made. [...] An organization's asset management and asset management system maturity are reflected in its capabilities, which are essential elements enabling success." ;
  iso:pdmRelevance "medium" .

iso:term_capacity_building a iso:Concept ;
  rdfs:label "capacity building" ;
  iso:provenanceStandard "ISO 55011:2024" ;
  iso:provenanceClause "3.1" ;
  iso:definition "provision of relevant competencies, skills, knowledge, experience, and the associated funding, technology and other resources that enable individuals or organizations to accomplish new tasks to achieve asset management objectives" ;
  iso:pdmRelevance "low" .

