  iso:pdmRelevance "low" .

iso:term_am_culture a iso:Concept ;
  rdfs:label "asset management culture" ;
  iso:provenanceStandard "ISO 55012:2024" ;
  iso:provenanceClause "4.3" ;
  iso:definition "An asset management culture which supports people in recognizing and aligning with the organization's vision can improve the organization's performance, motivate people and coordinate their behaviour, which in turn can help achieve the organization's overall asset management objectives." ;
  iso:pdmRelevance "medium" .

iso:attribute_vision a iso:Concept ;
  rdfs:label "vision (leadership attribute)" ;
  iso:provenanceStandard "ISO 55012:2024" ;
  iso:provenanceClause "5.2.2" ;
  iso:definition "Effective leaders have a clear vision for the organization which they articulate and communicate to all personnel in the organization." ;
  iso:pdmRelevance "low" .

iso:attribute_commitment a iso:Concept ;
  rdfs:label "commitment (leadership attribute)" ;
  iso:provenanceStandard "ISO 55012:2024" ;
  iso:provenanceClause "5.2.3" ;
  iso:definition "Effective leaders are passionate about their work and are committed to seeing their vision become a reality." ;
  iso:pdmRelevance "low" .

iso:attribute_integrity a iso:Concept ;
  rdfs:label "integrity (leadership attribute)" ;
  iso:provenanceStandard "ISO 55012:2024" ;
  iso:provenanceClause "5.2.4" ;
  iso:definition "By embracing and advocating for the principles and values that underlie their strategic plans, and in particular by ensuring that their own actions reflect these principles, positive leaders act as important examples to other personnel of the expectations of the organizational culture." ;
  iso:pdmRelevance "low" .

iso:attribute_communicative a iso:Concept ;
  rdfs:label "communicative (leadership attribute)" ;
  iso:provenanceStandard "ISO 55012:2024" ;
