  iso:provenanceStandard "ISO/TS 55010:2019" ;
  iso:provenanceClause "6.2" ;
  iso:definition "Organizations use their information systems to register, manage, analyse and report on asset data and activities. These systems may comprise computer hardware, computer software, databases and data warehouses, telecommunications to connect hardware to form a network, and people to operate the systems (human resources and procedures)." ;
  iso:pdmRelevance "medium" .

iso:term_data_management a iso:Concept ;
