iso:term_non_financial_asset_register a iso:Concept ;
  rdfs:label "non-financial asset register" ;
  iso:provenanceStandard "ISO/TS 55010:2019" ;
  iso:provenanceClause "7.3" ;
  iso:definition "The non-financial asset registers are the organization's definitive key source of information for all the assets it manages and operates (tangible and intangible)." ;
  iso:pdmRelevance "high" .

iso:term_shared_granularity a iso:Concept ;
  rdfs:label "shared asset granularity" ;
  iso:provenanceStandard "ISO/TS 55010:2019" ;
  iso:provenanceClause "7.4" ;
  iso:definition "In order to collaborate, there needs to be an organization-wide consensus on shared granularity, i.e. the asset breakdown detail at which financial and non-financial data will be shared. That consensus needs to be formalized in a dictionary of standard descriptions of the assets in the shared granularity and complied with across all departmental asset register platforms. Assets at that level of granularity need to share the same identification code to ensure integrity, so that data in the different departmental asset registers can be reported together for completeness." ;
  iso:pdmRelevance "high" .

iso:term_asset_register_alignment a iso:Concept ;
  rdfs:label "asset register alignment" ;
  iso:provenanceStandard "ISO/TS 55010:2019" ;
  iso:provenanceClause "7.4" ;
  iso:definition "Facilitating alignment between financial and non-financial asset management processes requires a common aspect/tag to be contained within each register. Without such commonality, full alignment will be difficult to achieve." ;
  iso:pdmRelevance "high" .

iso:term_financial_planning a iso:Concept ;
  rdfs:label "financial planning for asset management" ;
  iso:provenanceStandard "ISO/TS 55010:2019" ;
  iso:provenanceClause "8.1" ;
  iso:definition "Financial planning for asset management is an integral part of the overarching asset management process. Asset management planning aims to achieve both financial and non-financial objectives while balancing performance, cost and risk over the total life cycle of the asset systems." ;
