  iso:provenanceStandard "ISO/TS 55010:2019" ;
  iso:provenanceClause "8.3" ;
  iso:definition "Long-term financial planning builds on the outputs from the asset management planning and capital investment planning. It includes all annual operation and maintenance costs over the planning timeframe. It is the process of aligning financial capacity with long-term service or product delivery objectives." ;
  iso:pdmRelevance "medium" .

iso:term_budgeting a iso:Concept ;
